(()=>{'use strict';const core=window.KingdomI18nCore,originals=new WeakMap(),attributes=new WeakMap(),controls=[],key='kingdom-language';let language='zh';try{language=localStorage.getItem(key)==='en'?'en':'zh'}catch{}const ignored=n=>n.parentElement?.closest('script,style,[data-i18n-ignore]');
function text(node){if(ignored(node))return;const current=node.nodeValue,old=originals.get(node);let source=old&&current===old.last?old.source:current;if(!/[\u3400-\u9fff]/.test(source)){if(old)originals.delete(node);return}const next=core.translate(source,language);originals.set(node,{source,last:next});if(next!==current)node.nodeValue=next}
function attrs(e){if(e.closest('[data-i18n-ignore],script,style'))return;let store=attributes.get(e);if(!store){store={};attributes.set(e,store)}for(const name of ['title','aria-label','placeholder','alt']){if(!e.hasAttribute(name))continue;const current=e.getAttribute(name),old=store[name],source=old&&old.last===current?old.source:current;if(!/[\u3400-\u9fff]/.test(source))continue;const next=core.translate(source,language);store[name]={source,last:next};if(next!==current)e.setAttribute(name,next)}}
function walk(node){if(node.nodeType===3){text(node);return}if(node.nodeType!==1||node.matches('script,style,[data-i18n-ignore]'))return;attrs(node);for(const child of node.childNodes)walk(child)}
function apply(){document.documentElement.lang=language==='en'?'en':'zh-CN';for(const control of controls)control.value=language;walk(document.documentElement);document.dispatchEvent(new CustomEvent('kingdom-language-change',{detail:{language}}))}
function setLanguage(value){language=value==='en'?'en':'zh';try{localStorage.setItem(key,language)}catch{}apply()}
function picker(id){const row=document.createElement('label');row.className='language-picker';row.dataset.i18nIgnore='true';row.innerHTML='<span>语言 / Language</span><select id="'+id+'" aria-label="语言 / Language"><option value="zh">简体中文</option><option value="en">English</option></select>';const select=row.querySelector('select');select.value=language;select.onchange=()=>setLanguage(select.value);controls.push(select);return row}
document.querySelector('.intro-content').prepend(picker('language-setup'));document.querySelector('#pause-screen').append(picker('language-pause'));
// Translate presentation only: country IDs, queue kinds and saved simulation data never change.
for(const name of ['fillText','strokeText','measureText']){const base=CanvasRenderingContext2D.prototype[name];CanvasRenderingContext2D.prototype[name]=function(value,...args){return base.call(this,core.translate(value,language),...args)}}
const pending=new Set();let scheduled=false;const observer=new MutationObserver(records=>{for(const r of records){if(r.type==='childList')for(const node of r.addedNodes)pending.add(node);else pending.add(r.target)}if(!scheduled&&pending.size){scheduled=true;queueMicrotask(()=>{scheduled=false;for(const n of pending)if(n.isConnected)walk(n);pending.clear()})}});observer.observe(document.documentElement,{subtree:true,childList:true,characterData:true,attributes:true,attributeFilter:['title','aria-label','placeholder','alt']});
window.KingdomI18n={get language(){return language},translate:value=>core.translate(value,language),setLanguage};apply();
})();
